    out = [row[:] for row in grid]
    row_starts = range(1, h - 4, 7)
    col_starts = range(1, w - 4, 7)
    colors = {}
    for r0 in row_starts:
        for c0 in col_starts:
            colors[(r0, c0)] = grid[r0 + 2][c0 + 2]
    counts = {}
    for color in colors.values():
        counts[color] = counts.get(color, 0) + 1
    if not counts:
        return out
    ordinary = max(counts, key=counts.get)
    for (r0, c0), color in colors.items():
        if color == ordinary:
            continue
        rr, cc = r0 + 2, c0 + 2
        # Extend from this tile center to the right through its 2-cell gutter.
        for x in (c0 + 5, c0 + 6):
            if x < w and grid[rr][x] == 0:
                out[rr][x] = color
        # Extend downward through its 2-cell gutter.
        for y in (r0 + 5, r0 + 6):
            if y < h and grid[y][cc] == 0:
                out[y][cc] = color
    return out
