    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def active_bands(lines):
        bands = []
        i = 0
        while i < len(lines):
            if any(lines[i]):
                start = i
                while i + 1 < len(lines) and any(lines[i + 1]):
                    i += 1
                bands.append((start, i))
            i += 1
        return bands

    row_bands = active_bands(grid)
    col_bands = active_bands([[grid[r][c] for r in range(h)] for c in range(w)])
    # Discard clipped edge fragments; full tile bands share the modal size.
    rh = {}
    cw = {}
    for a, b in row_bands:
        rh[b - a + 1] = rh.get(b - a + 1, 0) + 1
    for a, b in col_bands:
        cw[b - a + 1] = cw.get(b - a + 1, 0) + 1
    if not rh or not cw:
        return out
    rsize = max(rh, key=rh.get)
    csize = max(cw, key=cw.get)
    row_bands = [band for band in row_bands if band[1] - band[0] + 1 == rsize]
    col_bands = [band for band in col_bands if band[1] - band[0] + 1 == csize]
    if not row_bands or not col_bands:
        return out

    colors = {}
    for i, (r0, r1) in enumerate(row_bands):
        for j, (c0, c1) in enumerate(col_bands):
            colors[i, j] = grid[(r0 + r1) // 2][(c0 + c1) // 2]
