    # signal tiles, through the tile's interior rows (excluding its frame).
    for i, (r0, r1) in enumerate(row_bands):
        for color in set(colors[i, j] for j in range(len(col_bands))) - {ordinary, 0}:
            js = [j for j in range(len(col_bands)) if colors[i, j] == color]
            if len(js) < 2:
                continue
            for j in range(min(js), max(js)):
                _, left_end = col_bands[j]
                right_start, _ = col_bands[j + 1]
                for r in range(r0 + 1, r1):
                    for c in range(left_end + 1, right_start):
